-- Biology Units 4-6 hierarchy, GCE A/L 2017 (NIE)
with v as (select id from public.syllabus_versions where code='GCE_AL_2017'), bio as (select id from public.subjects where name='Biology')
insert into public.syllabus_competencies(syllabus_version_id,subject_id,code,title,description,position)
select v.id,bio.id,x.code,x.title,x.description,x.position from v cross join bio cross join (values ('4.1.0','Explores structure, growth and development of plants','Official NIE 2017 Biology competency.',1),('4.2.0','Examines resource acquisition and transport in vascular plants','Official NIE 2017 Biology competency.',2),('4.3.0','Explores the diversity of nutritional processes in plants','Official NIE 2017 Biology competency.',3),('4.4.0','Inquires into reproductive process in plants','Official NIE 2017 Biology competency.',4),('4.5.0','Explores plant responses to internal and external signals','Official NIE 2017 Biology competency.',5),('5.1.0','Explores structure, growth and development of animals','Official NIE 2017 Biology competency.',1),('5.2.0','Explores nutrition in animals','Official NIE 2017 Biology competency.',2),('5.3.0','Investigates circulation and gas exchange of animals','Official NIE 2017 Biology competency.',3),('5.4.0','Explores immunity','Official NIE 2017 Biology competency.',4),('5.5.0','Explores osmoregulation and excretion','Official NIE 2017 Biology competency.',5),('5.6.0','Investigates the structures and functions involved in nervous coordination','Official NIE 2017 Biology competency.',6),('5.7.0','Explores endocrinal regulation and homeostasis','Official NIE 2017 Biology competency.',7),('5.8.0','Inquires into the reproductive process in animals','Official NIE 2017 Biology competency.',8),('5.9.0','Inquires into supporting systems and movement in organisms','Official NIE 2017 Biology competency.',9),('6.1.0','Explores the basic principles of genetics for applications','Official NIE 2017 Biology competency.',1)) x(code,title,description,position) where not exists(select 1 from public.syllabus_competencies c where c.syllabus_version_id=v.id and c.subject_id=bio.id and c.code=x.code);
with v as (select id from public.syllabus_versions where code='GCE_AL_2017'), bio as (select id from public.subjects where name='Biology')
insert into public.syllabus_competency_levels(competency_id,syllabus_version_id,subject_id,code,title,description,position)
select c.id,v.id,bio.id,x.code,x.title,x.description,x.position from v cross join bio cross join (values ('4.1.1','4.1.0','Examines different types of tissues and relates the structure of plant tissues to their functions','Plant meristems and dermal, ground and vascular tissues.',1),('4.1.2','4.1.0','Examines the changes taking place in the growth and development process of a plant','Primary structure, secondary growth and wood formation.',2),('4.2.1','4.2.0','Investigates the shoot architecture and light capture','Shoot and leaf architecture, light capture and leaf area index.',1),('4.2.2','4.2.0','Investigates the process of gaseous exchange in plants','Leaf anatomy, stomata and gaseous exchange.',2),('4.2.3','4.2.0','Investigates the process of water absorption in plants','Water potential, root absorption and mineral uptake.',3),('4.2.4','4.2.0','Investigates the upward movement of water and minerals in plants','Xylem transport and ascent of sap.',4),('4.2.5','4.2.0','Investigates the processes involved in transport of materials in plants','Phloem transport and translocation.',5),('4.2.6','4.2.0','Investigates the processes of water loss in plants','Transpiration, guttation and water-loss factors.',6),('4.3.1','4.3.0','Investigates the modes of nutrition of plants','Autotrophic nutrition and plant relationships.',1),('4.3.2','4.3.0','Investigates nutritional requirement for the optimal growth of plants','Essential elements and nutrient deficiencies.',2),('4.4.1','4.4.0','Uses trends in life cycles to relate adaptations of plants for terrestrial life','Alternation of generations and plant life cycles.',1),('4.4.2','4.4.0','Examines structures and functions associated with sexual reproduction in flowering plants','Flowers, pollination, fertilization, seeds and germination.',2),('4.5.1','4.5.0','Inquires into types of movement in plants in response to different stimuli','Plant movements and tropic responses.',1),('4.5.2','4.5.0','Investigates the role of plant growth substances/regulators/hormones in response to different stimuli','Plant growth substances and hormones.',2),('4.5.3','4.5.0','Investigates response of plants to some biotic and abiotic stresses','Plant stress and defence.',3),('5.1.1','5.1.0','Relates the structure of animal tissues to their functions','Animal tissues.',1),('5.2.1','5.2.0','Explores heterotrophic nutrition in animals','Holozoic nutrition, feeding mechanisms and symbiosis.',1),('5.2.2','5.2.0','Relates the structure of the human digestive system to its functions','Human digestion, nutrition and disorders.',2),('5.3.1','5.3.0','Investigates the organization of circulatory systems in animals','Circulatory system types.',1),('5.3.2','5.3.0','Relates the structure of the human circulatory system to its functions','Heart, vessels, cardiac cycle and blood pressure.',2),('5.3.3','5.3.0','Inquires into the role of blood','Blood pigments, transport, clotting and blood groups.',3),('5.3.4','5.3.0','Explores the diversity of respiratory structures in the animal kingdom','Animal respiratory structures.',4),('5.3.5','5.3.0','Relates the structure of the human respiratory system to its functions','Ventilation, gas exchange and respiratory disorders.',5),('5.4.1','5.4.0','Explores types of immunity','Innate/acquired immunity and immune disorders.',1),('5.5.1','5.5.0','Examines the relationship between metabolism and excretory substances','Excretion and nitrogenous wastes.',1),('5.5.2','5.5.0','Investigates the diversity of excretory structures of organisms','Animal excretory structures.',2),('5.5.3','5.5.0','Investigates the gross functioning of the human urinary system','Kidney, nephron, urine formation and disorders.',3),('5.6.1','5.6.0','Inquires into the processes and systems involved in coordination','Nervous and endocrine coordination.',1),('5.6.2','5.6.0','Investigates the gross structure and functions of the human nervous system','Brain, spinal cord and autonomic nervous system.',2),('5.6.3','5.6.0','Explores how nerve impulses are generated and transmitted','Action potentials, synapses and reflex arcs.',3),('5.6.4','5.6.0','Explores injuries and common disorders of the nervous system','Nervous system disorders.',4),('5.6.5','5.6.0','Explores the functions of different sensory structures in human','Sensory receptors.',5),('5.6.7','5.6.0','Relates the structures of the eye and ear to their functions','Eye and ear.',6),('5.6.8','5.6.0','Investigates the basic structure and functions of the human skin','Skin and homeostasis.',7),('5.7.1','5.7.0','Analyses the role of human endocrine system','Endocrine glands, hormones and feedback.',1),('5.7.2','5.7.0','Investigates how a constant internal environment is maintained within a range','Human homeostasis.',2),('5.8.1','5.8.0','Inquires into different types of reproduction in animals','Asexual and sexual reproduction.',1),('5.8.2','5.8.0','Inquires structure and functions of male reproductive system','Male reproductive system.',2),('5.8.3','5.8.0','Inquires into structure and functions of female reproductive system','Female reproductive system.',3),('5.8.4','5.8.0','Inquires into the processes involved in fertilization up to birth','Fertilization, pregnancy, birth and lactation.',4),('5.8.5','5.8.0','Develops an awareness on reproductive health','Reproductive health.',5),('5.9.1','5.9.0','Inquires into the structure and functions of skeletal systems and movement of animals','Animal skeletons and movement.',1),('5.9.2','5.9.0','Investigates the structure and functions of the axial skeleton of man','Human axial skeleton.',2),('5.9.3','5.9.0','Investigates the structure and functions of the appendicular skeleton of man','Human appendicular skeleton.',3),('5.9.4','5.9.0','Investigates the main types of joints and mechanism of skeletal muscle movement','Joints and skeletal muscle movement.',4),('6.1.1','6.1.0','Inquires the scientific basis of Mendel’s experiments','Mendelian inheritance.',1),('6.1.2','6.1.0','Examines the patterns of inheritance of Mendelian characters in human','Human Mendelian inheritance and pedigrees.',2),('6.1.3','6.1.0','Uses concepts and principles to explain genetic patterns that deviate from Mendel’s laws','Non-Mendelian inheritance.',3),('6.1.4','6.1.0','Investigates evolution of life by using changes in gene frequencies','Population genetics.',4),('6.1.5','6.1.0','Explores the basic concepts in plant and animal breeding','Plant and animal breeding.',5)) x(code,competency_code,title,description,position) join public.syllabus_competencies c on c.syllabus_version_id=v.id and c.subject_id=bio.id and c.code=x.competency_code where not exists(select 1 from public.syllabus_competency_levels cl where cl.syllabus_version_id=v.id and cl.subject_id=bio.id and cl.code=x.code);
with cl as (select * from public.syllabus_competency_levels where syllabus_version_id=(select id from public.syllabus_versions where code='GCE_AL_2017') and subject_id=(select id from public.subjects where name='Biology') and code like any(array['4.%','5.%','6.%'])) insert into public.syllabus_topics(unit_id,title,position) select u.id,cl.code || ' — ' || cl.title,100+cl.position from cl join public.syllabus_units u on u.subject_id=cl.subject_id and u.syllabus_version_id=cl.syllabus_version_id and u.position=case when cl.code like '4.%' then 4 when cl.code like '5.%' then 5 else 6 end where not exists(select 1 from public.syllabus_topics t where t.unit_id=u.id and t.title=cl.code || ' — ' || cl.title);
with cl as (select * from public.syllabus_competency_levels where syllabus_version_id=(select id from public.syllabus_versions where code='GCE_AL_2017') and subject_id=(select id from public.subjects where name='Biology') and code like any(array['4.%','5.%','6.%'])) insert into public.syllabus_subtopics(topic_id,title,description,position) select t.id,'Core learning outcomes','Official NIE 2017 Biology competency-level learning area.',1 from cl join public.syllabus_topics t on t.title=cl.code || ' — ' || cl.title where not exists(select 1 from public.syllabus_subtopics st where st.topic_id=t.id and st.title='Core learning outcomes');
with o(level_code,statement,position) as (values ('4.1.1','relate the structure of plant tissues to their functions',1),('4.1.2','describe primary and secondary growth in plants',1),('4.2.1','describe adaptations of shoots and leaves for efficient light capture',1),('4.2.2','explain gaseous exchange through stomata and the factors affecting stomatal action',1),('4.2.3','relate root anatomy to absorption of water and minerals',1),('4.2.4','explain the upward movement of water and minerals in plants',1),('4.2.5','describe the mechanism of phloem translocation',1),('4.2.6','describe transpiration, guttation and factors affecting water loss',1),('4.3.1','describe modes of nutrition and nutritional relationships in plants',1),('4.3.2','describe functions and deficiency symptoms of essential mineral nutrients',1),('4.4.1','explain alternation of generations in terrestrial plants',1),('4.4.2','describe pollination, fertilization, seed and fruit development in flowering plants',1),('4.5.1','explain major types of plant movement in response to stimuli',1),('4.5.2','state functions and agricultural uses of major plant growth substances',1),('4.5.3','explain selected plant responses to biotic and abiotic stress',1),('5.1.1','relate structural features of animal tissues to their functions',1),('5.2.1','explain stages and mechanisms of heterotrophic and holozoic nutrition',1),('5.2.2','relate the structure of the human digestive system to its functions',1),('5.3.1','compare major circulatory systems in animals',1),('5.3.2','relate the structure of the human circulatory system to its functions',1),('5.3.3','explain the role of blood, clotting and blood-group systems',1),('5.3.4','describe the diversity of respiratory structures in animals',1),('5.3.5','relate the structure of the human respiratory system to ventilation and gas exchange',1),('5.4.1','explain innate and acquired immunity and the roles of immune cells',1),('5.5.1','relate metabolism to nitrogenous excretory products',1),('5.5.2','describe the diversity of excretory structures in animals',1),('5.5.3','explain urine formation and the homeostatic functions of the human kidney',1),('5.6.1','compare nervous and endocrine systems as coordination systems',1),('5.6.2','describe the organization and functions of the human nervous system',1),('5.6.3','explain generation and transmission of nerve impulses',1),('5.6.4','describe common disorders of the nervous system',1),('5.6.5','describe the functions of different human sensory receptors',1),('5.6.7','relate the structures of the human eye and ear to their functions',1),('5.6.8','explain the structure and functions of human skin',1),('5.7.1','describe endocrine glands, hormones and feedback mechanisms',1),('5.7.2','explain human homeostasis including temperature, glucose and osmoregulation',1),('5.8.1','compare asexual and sexual reproduction in animals',1),('5.8.2','describe the male reproductive system and hormonal regulation of spermatogenesis',1),('5.8.3','describe the female reproductive system and hormonal regulation of the menstrual cycle',1),('5.8.4','explain fertilization, pregnancy, birth and lactation',1),('5.8.5','explain reproductive health, contraception, STIs and assisted reproduction',1),('5.9.1','compare hydrostatic, exoskeletal and endoskeletal support systems',1),('5.9.2','relate the human axial skeleton to its functions and upright posture',1),('5.9.3','relate the human appendicular skeleton to movement and posture',1),('5.9.4','explain major joints and the basic sliding-filament mechanism of muscle movement',1),('6.1.1','describe Mendelian inheritance and predict ratios from genetic crosses',1),('6.1.2','analyze Mendelian inheritance in human families using pedigree charts',1),('6.1.3','explain non-Mendelian inheritance patterns and sex-linked inheritance',1),('6.1.4','explain Hardy-Weinberg equilibrium and changes in gene frequencies',1),('6.1.5','explain principles and techniques of plant and animal breeding',1)) insert into public.syllabus_learning_outcomes(subtopic_id,competency_id,competency_level_id,statement,position) select st.id,cl.competency_id,cl.id,o.statement,o.position from o join public.syllabus_competency_levels cl on cl.code=o.level_code and cl.syllabus_version_id=(select id from public.syllabus_versions where code='GCE_AL_2017') and cl.subject_id=(select id from public.subjects where name='Biology') join public.syllabus_subtopics st on st.title='Core learning outcomes' join public.syllabus_topics t on t.id=st.topic_id and t.title=cl.code || ' — ' || cl.title where not exists(select 1 from public.syllabus_learning_outcomes lo where lo.subtopic_id=st.id and lo.statement=o.statement);